WoWpoCesku_BossLore = {

["Ragefire Chasm"] = {
    ["Oggleflint"] = [[Vůdce troggů z Ragefire. Ti vládli hlubinám jeskyně bez soupeře, dokud se do ní nenastěhovali kultisté Searing Blade. Troggové se jim nedokázali ubránit, ustoupili k východu z jeskyně a trpělivě čekají, až nechtění hosté zase odejdou. Šamani Hordy se s nimi kdysi pokusili vyjednat mír, ale nepochodili.]],

    ["Taragaman the Hungerer"] = [[Felguard, démonický válečník, který vypadá jako vůdce kultu Searing Blade. Ve skutečnosti je podle příběhu spíš návnada: má lákat mladé dobrodruhy Hordy do pasti, zatímco skuteční vůdci jsou Jergosh a Bazzalan. Z ohnivých hlubin se snaží svým démonickým vlivem kazit obyvatele Orgrimmaru.]],

    ["Jergosh the Invoker"] = [[Orčí černokněžník, který zavrhl ideály svého lidu a oddal se temným a démonickým uměním. Vedl kultisty Searing Blade a patřil do Shadow Council. V Ragefire Chasm střežil Blood Filled Orb, předmět potřebný k přivolání démona Zelemara Zuřivého. Jeho plány byly tak vážné, že upoutaly pozornost samotného Thralla.

SPOILER: Když se vrátila Pálivá legie, svolal Gul'dan přeživší vůdce Shadow Council, mezi nimi i Jergosha. Ten byl s Braelyn Firehand poslán do Caer Darrow pro Book of Medivh, který měl Kult zatracených. Knihu získal, ale tam ho zabil dobrodruh černokněžník.]],

    ["Bazzalan"] = [[Satyr, démon a spolu s Jergoshem skutečný vůdce kultu Searing Blade. Jeho pohnutky nejsou jasné, ale jako všichni satyrové je mrštný a lstivý. Bojuje jako zloděj: používá Sinister Strike a občas otráví svého soupeře.]],
},


["Wailing Caverns"] = {
    ["Lady Anacondra"] = [[Dřív se jmenovala Scarletleaf a byla to mladá noční elfka, druidka. Jako první se přihlásila do výpravy, kterou si Naralex sám vytyčil: obnovit život v pustých Barrens. Když Naralexova noční můra zkazila celé jeskyně, odhodila své jméno i minulost. V hlavě měla odteď strašlivou představu plazí budoucnosti Azerothu. Stala se jedním z Pánů Tesáků (Fanglords) a v Wailing Caverns je první z nich.]],

    ["Lord Cobrahn"] = [[Býval to Jarlaxla, noční elf, který se v Cenarionském kruhu proslavil svou obratností v proměnách do zvířecích podob. Zkáza jeskyní jeho nadání pokřivila: zdokonalil si smrtonosnou hadí podobu a přijal jméno Cobrahn, které mělo odpovídat jeho nové krutosti. Je největší z druidů, má drápy na pravé ruce a doprovázejí ho zkažení pytoni (deviate). Z Pánů Tesáků je nejsnazší, ale při boji křičí: „Nikdy nevzbudíš snícího!“, což míří na Naralexe.]],

    ["Lord Pythas"] = [[Býval to Aryn, noční elf a bojovník, přítel Naralexe z dětství a jeden z jeho osobních strážců. Naučil se sice základy druidismu, ale proti zkáze, která mu brala rozum, byl bezbranný. Přijal jméno Pythas a spojil bojové umění s druidskou mocí. Dnes slouží Druidům Tesáků, kteří stojí proti věrným žákům Naralexe. Je nejtvrdší z Pánů Tesáků: léčí se, sesílá blesky, uspává a rozráží hromem.]],

    ["Lord Serpentis"] = [[Kdysi mocný a vážený druid. Chtěl se stát shan'do, ctěným učitelem jako Naralex. Když mu přišla na mysl šílenost, shromáždil kolem sebe své bratry a založil Druidy Tesáků. Je hlavním protivníkem Wailing Caverns a Pán Tesáků, který celou sektu vede.]],

    ["Kresh"] = [[Obří želva, která žije v jezírku uvnitř jeskyní. Sama nenapadá, takže zabít ji není povinné.]],

    ["Mutanus the Devourer"] = [[Zjeví se při probouzení Naralexe jako zhmotněná noční můra. Čím víc se snaží druid z magického spánku vyprostit, tím víc se ho jeho vlastní zkažená představa snaží pohltit.

SPOILER: Pokud se skupině podaří Mutana porazit, Naralex se probudí a může pokračovat ve své snaze o obnovu Barrens.]],
},

["The Deadmines"] = {
    ["Rhahk'Zor"] = [[Ogr, předák dělníků v Deadmines pod Edwinem VanCleefem. Dohlížel na práci v dolech a hlídá první dveře dungeonu. Je velmi silný a má hodně brnění. V pozdějším příběhu ho zabije posádka pirátů Jeriase Bloodveina.]],

    ["Sneed"] = [[Goblin a hlavní dřevorubec (lumbermaster) Defias Brotherhood. V Mast Room kácí dřevo pro stavbu lodi a bojuje ve stroji zvaném Sneed's Shredder. Jakmile ho zničíš, vystoupí a bojuje sám. Ve vzdáleném příběhu ho zabije Bloodveinova posádka.]],

    ["Gilnid"] = [[Goblin, strojník a hlavní tavič Edwina VanCleefa v Deadmines. Dohlíží na tavírnu a stará se, aby obří loď měla dost děl a munice. Byl velmi nadaný, ale jeho pokusy bývaly tak nebezpečné, že ho prý vyhnali z Booty Bay. Hrubě pohání dělníky: „Chce někdo pauzu? Tak to ne!“]],

    ["Mr. Smite"] = [[Tauren, první důstojník na VanCleefově lodi. Rád si hraje se svými oběťmi: nechá je věřit, že mají šanci, a mezitím sahá po stále nebezpečnější zbrani. Jeho arzenál začíná Thief's Blade, pokračuje dvěma Reavery a končí Mighty Hammerem. Při boji omračuje Warstompem, zatímco sahá do truhly pro další zbraň.]],

    ["Captain Greenskin"] = [[Goblinský kapitán na VanCleefově lodi. Pochází z Booty Bay, kde dřív velel celé flotile pirátských lodí. S sebou má za prvního důstojníka Mr. Smitea a za kuchaře Cookieho. V pozdějším příběhu ho zabijí při útoku Aliance na Deadmines.]],

    ["Edwin VanCleef"] = [[Býval to architekt a mistr inženýr, vůdce cechu kameníků (Stonemasons Guild), který po první válce obnovoval zničený Stormwind. Považovali ho za jednoho z největších lidských inženýrů. Šlechta (House of Nobles) kameníky nedostatečně zaplatila. Když dělníci vyrazili protestovat, při nepokojích zahynula královna Tiffin. Král Varian z toho obvinil dělníky a VanCleef musel utéct se svými lidmi.

Ve Westfallu z vyhnaných kameníků vytvořil zločineckou organizaci Defias Brotherhood. Využil svůj výcvik v umění skrývání a lsti a sídlo zřídil v Deadmines. Kameníci i šlechta byli přitom pod vlivem lady Katrany Prestor.

SPOILER: Lady Prestor je ve skutečnosti Onyxia v lidské podobě a ona celý dluhový spor vyvolala. Aliancí vyslaní dobrodruzi VanCleefa porazí na jeho lodi, ale později jeho dcera Vanessa Brotherhood obnoví.]],

    ["Cookie"] = [[Murlok, kuchař na VanCleefově lodi. Najdeš ho až po porážce samotného VanCleefa a je to volitelný boss.]],
},


["Shadowfang Keep"] = {
    ["Rethilgore"] = [[Jeden z nejzuřivějších worgenů, kterému Arugal svěřil hlídání vězňů v kobkách. Držel tu zajatce jako Deathstalkera Adamanta, Sorcerera Ashcrombeho a Landena Stilwella. Dnes je mrtvý a jeho duch se zjeví, když ho zavolá Baron Silverlaine.]],

    ["Razorclaw the Butcher"] = [[Nemrtvý worgen z kuchyně Shadowfang Keep. Podle příběhu pobil mnoho nevinných lidí, když ho sem přivedl jeho pán Arugal, a získal tak přezdívku Řezník. Patřil do smečky Shadowfang pod Arugalovým velením.]],

    ["Baron Silverlaine"] = [[Šlechtic z království Gilneas, dnes duch, který straší v Shadowfang Keep. Býval pánem tvrze, než padla. Jeho i jeho rodinu zabili worgeni, které Arugal přivolal ze Smaragdového snu, aby pomohli Gilneasu proti Scourge, a kteří se pak obrátili proti vlastním lidem. Jeho duch dodnes straší v hradu a volá worgení duchy, aby napadli vetřelce, tedy přesně ty bestie, které ho kdysi zabily.]],

    ["Commander Springvale"] = [[Paladin, velitel vojska pod Baronem Silverlainem. Patřil k Rytířům Stříbrné ruky a sloužil království Gilneas. Zahynul spolu s ostatními obyvateli tvrze, když zaútočili worgeni. Jeho duch dodnes straší v kapli a „bije posvátnou silou, aby pomstil svého pána“.]],

    ["Odo the Blindwatcher"] = [[Slepý worgen, který žil v rozvrzaném dřevěném přístavku pověšeném na boku tvrze se svými dvěma netopýry. I bez zraku si poradil: spoléhal na ostatní smysly. Dnes už není samostatný boss, ale duch, kterého volá Baron Silverlaine.]],

    ["Fenrus the Devourer"] = [[Obrovský worg (vlk, ne worgen) a mazlíček Archmage Arugala. Je „neuvěřitelně velký“, možná zvětšený temnou magií. Dokáže zařvat tak, že ho slyšet po celé instanci, a otráví nepřítele jedovatými slinami. Jeho jméno odkazuje na Fenrira, obřího vlka ze severské mytologie, který se má za Ragnaröku osvobodit.]],

    ["Wolf Master Nandos"] = [[Mrtvý worgen, kdysi pán worgů (vlků), který sloužil Arugalovi. Před úpravou hry byl posledním Arugalovým pohůnkem, který hráčům stál v cestě. Dnes se zjevuje jako duch, když ho zavolá Baron Silverlaine.]],

    ["Archmage Arugal"] = [[Býval to vážený arcimág z Dalaranu a člen Kirin Tor. Sloužil také jako královský arcimág Gilneasu, i když někteří pochybovali o jeho schopnostech, protože hodně spoléhal na očarované předměty. Když se za třetí války ke gilneaské severní hranici přiblížil Scourge, požádal ho král Genn Greymane o pomoc. Arugal navrhl přivolat worgeny, záhadnou rasu, kterou zkoumal. Zpočátku uspěl, ale worgeni se obrátili proti gilneaským vojákům a rozšířili po království kletbu proměny.

Trýzněn vinou přijal worgeny za své děti a ustoupil do Shadowfang Keep, které dřív patřilo Baronu Silverlainovi. Založil worgenský kult a pomocí magie držel pod kontrolou smečky Shadowfang a Moonrage. Jeho strážcem byl obří Fenrus.

SPOILER: Agenti Hordy Arugala zavraždili. Později ho Lich King vzkřísil jako stín ve službách Scourge a poslal do Grizzly Hills proměňovat lovce na worgeny. Nakonec byl zničen a jeho duše odešla do Shadowlands.]],
},

["Blackfathom Deeps"] = {
    ["Ghamoo-ra"] = [[Obrovská želva, která žije v Pool of Ask'ar. Jedna z prastarých obyvatel potopeného chrámu.]],

    ["Lady Sarevess"] = [[Naga čarodějka ve službách kultu Twilight's Hammer. Dostala od kultu vlastní zátoku v Blackfathom Deeps a stále jí posílali čerstvé oběti. Prováděla rituály a magický výzkum, který měl vytvořit ochranná kouzla pro věřící, kteří uctívali hydru. Neuspěla: její nadřízená Domina ji obětovala Starým bohům jako trest. Tělo zůstalo na oltáři v dungeonu. Bojuje blesky.]],

    ["Gelihast"] = [[Murlok, který sídlí ve svatyni Shrine of Gelihast. Opatrně s jeho podřízenými: když mají málo životů, utíkají zpátky ke svému bossovi.]],

    ["Baron Aquanis"] = [[Vodní elementál, který stráží zříceniny Moonshrine.]],

    ["Twilight Lord Kelris"] = [[Ork, vůdce kultistů Twilight's Hammer v Blackfathom Deeps. Dohlížel na růst Aku'maie, hydry, ve které viděl „předzvěst návratu Starých bohů na Azeroth“. Vroucně je uctíval a chtěl vrátit svět do doby chaosu. Po Cataclysmu ho nový velitel Twilight Lord Bathiel popravil: nechal ho sežrat Aku'maiem.

SPOILER: Podle Season of Discovery Kelris původní setkání přežil a odešel do Searing Gorge, kde vedl Flamebringers.]],

    ["Aku'mai"] = [[Třihlavá hydra ve službách Starých bohů, „gigantické a prastaré zlo obdařené mocí Prázdnoty“. Je oblíbený mazlíček Starých bohů. Sídlí v Blackfathom Deeps, kdysi chrámu noční elfů zasvěceném Elune, a staletí sužuje Zoram Strand. Kult Twilight's Hammer ho objevil a považoval ho za znamení návratu Starých bohů. Kelris dohlížel na jeho růst a krmil ho kultisty. Nese malou část moci Starých bohů a údajně chce pohltit svět. Nakonec ho porazili šampioni Hordy i Aliance.]],
},

["The Stockade"] = {
    ["Targorr the Dread"] = [[Zajatý ork z Blackrocku, který čeká v Stockade na popravu. Byrokracie ve Stormwindu jeho trest zdržela, dokud ho nezabil dobrodruh.]],

    ["Kam Deepfury"] = [[Vězeň z klanu Dark Iron. Agenti Ironforge se ho pokusili zavraždit, aby se vyhnuli stormwindské byrokracii.]],

    ["Bazil Thredd"] = [[Vůdce vzpoury vězňů, kterou vyvolalo Defias Brotherhood. Je to lstivý zločinec, kterého musí dobrodruzi odstranit, aby se vzpoura potlačila. Jeho příběh ukazuje, jak hluboko sahá korupce Defias a jak zločinecké skupiny využívají vězení ke svým cílům.]],

    ["Dextren Ward"] = [[Vykradač hrobů, který skončil ve vězení poté, co prodával těla nekromantovi Morbentu Felovi. Rada Darkshire poslala dobrodruha, aby ho popravil.]],

},

["Gnomeregan"] = {
    ["Mekgineer Thermaplugg"] = [[Sicco Thermaplugg byl gnómský inženýr a hlavní poradce vrchního mechanika Gelbina Mekkatorquea. Žárlil, že ho nezvolili vrchním mechanikem a stal se největším zrádcem Gnomereganu.

Gnomeregan padl za třetí války, když na něj z hloubek zaútočili troggové a po pětiletém obléhání prorazili inženýrskou čtvrť. Když Gelbin hledal radu, jak invazi zastavit, navrhl Sicco město zaplavit radioaktivním plynem. Zfalšoval údaje, aby působil bezpečně, a tajně doufal, že plyn zabije mnoho gnómů, aby mohl obvinit Gelbina a uchopit moc.

SPOILER: Plyn byl smrtonosnější, než čekal: během několika dní zabil zhruba osmdesát procent obyvatel a přeživší, včetně samotného Thermaplugga, zmutoval v malomocné gnómy. Šílený Thermaplugg se prohlásil za krále gnómů a vládl ozářeným ruinám se svými malomocnými gnómy a troggy. Nakonec ho porazili při operaci Gnomeregan, vojenské akci, kterou vedl Gelbin.]],
},

}
